{
  "title": "市场订单",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "orderId",
    "amount"
  ],
  "properties": {
    "orderId": {
      "type": "string",
      "description": "订单唯一编号。"
    },
    "amount": {
      "type": "number",
      "minimum": 0,
      "description": "订单金额。"
    },
    "currency": {
      "type": "string",
      "enum": [
        "CNY",
        "USD"
      ],
      "description": "结算币种。"
    }
  }
}
